I see that the `ServerCertificateSelector` class directly calls static methods from the `CertificateUtils` class. To test the logging behavior when certificate fetching fails, we need to mock these static methods. However, mocking static methods directly is not straightforward in C#. Instead, we can use the wrapper pattern to make the `CertificateUtils` methods non-static and injectable.

Let's create a wrapper interface for `CertificateUtils` and refactor the `ServerCertificateSelector` class to use this wrapper. Then, we can mock the wrapper in our tests.

First, let's create the wrapper interface and the wrapper class:

```csharp
// ICertificateUtilsWrapper.cs
public interface ICertificateUtilsWrapper
{
    X509Certificate2 GetMachineCertificateBySubjectName(string subjectName);
    X509Certificate2 GetMachineCertificateByFile(string fileName, string password);
}

// CertificateUtilsWrapper.cs
public class CertificateUtilsWrapper : ICertificateUtilsWrapper
{
    public X509Certificate2 GetMachineCertificateBySubjectName(string subjectName)
    {
        return CertificateUtils.GetMachineCertificateBySubjectName(subjectName);
    }

    public X509Certificate2 GetMachineCertificateByFile(string fileName, string password)
    {
        return CertificateUtils.GetMachineCertificateByFile(fileName, password);
    }
}
```

Next, refactor the `ServerCertificateSelector` class to use the wrapper:

```csharp
// ServerCertificateSelector.cs
public sealed class ServerCertificateSelector
{
    private readonly ICertificateUtilsWrapper _certificateUtilsWrapper;
    private readonly ILogger _logger;
    private readonly TimeSpan _certificateRefreshRetryInterval = TimeSpan.FromSeconds(5);
    private readonly string _sslCertificateSubjectName;
    private readonly string _sslCertificateFileName;
    private readonly string _sslCertificatePassword;
    private readonly Timer _refreshTimer;
    private readonly TimeSpan _certRefreshFrequency;
    private X509Certificate2 _sslServerCertificate;

    public ServerCertificateSelector(string subjectName, int certRefreshFrequencyInSeconds = 0, ILogger logger = null, ICertificateUtilsWrapper certificateUtilsWrapper = null)
    {
        _logger = logger;
        _sslCertificateSubjectName = subjectName;
        _certificateUtilsWrapper = certificateUtilsWrapper ?? new CertificateUtilsWrapper();

        // First get certificate synchronously on current call
        _certRefreshFrequency = TimeSpan.Zero;
        GetServerCertificate(null);

        // Set up future timer, if needed
        // If the sync call failed to fetch certificate, we schedule the first call earlier (after certificateRefreshRetryInterval)
        _certRefreshFrequency = TimeSpan.FromSeconds(certRefreshFrequencyInSeconds);
        if (_certRefreshFrequency > TimeSpan.Zero)
            _refreshTimer = new Timer(GetServerCertificate, null, _sslServerCertificate == null ? _certificateRefreshRetryInterval : _certRefreshFrequency, _certRefreshFrequency);
    }

    public ServerCertificateSelector(string fileName, string filePassword, int certRefreshFrequencyInSeconds = 0, ILogger logger = null, ICertificateUtilsWrapper certificateUtilsWrapper = null)
    {
        _logger = logger;
        _sslCertificateFileName = fileName;
        _sslCertificatePassword = filePassword;
        _certificateUtilsWrapper = certificateUtilsWrapper ?? new CertificateUtilsWrapper();

        // First get certificate synchronously on current call
        _certRefreshFrequency = TimeSpan.Zero;
        GetServerCertificate(null);

        // Set up future timer, if needed
        // If the sync call failed to fetch certificate, we schedule the first call earlier (after certificateRefreshRetryInterval)
        _certRefreshFrequency = TimeSpan.FromSeconds(certRefreshFrequencyInSeconds);
        if (_certRefreshFrequency > TimeSpan.Zero)
            _refreshTimer = new Timer(GetServerCertificate, null, _sslServerCertificate == null ? _certificateRefreshRetryInterval : _certRefreshFrequency, _certRefreshFrequency);
    }

    public void EndTimer()
    {
        _refreshTimer?.Dispose();
    }

    public X509Certificate2 GetSslServerCertificate()
    {
        return _sslServerCertificate;
    }

    private void GetServerCertificate(object _)
    {
        try
        {
            if (_sslCertificateSubjectName != null)
            {
                _sslServerCertificate = _certificateUtilsWrapper.GetMachineCertificateBySubjectName(_sslCertificateSubjectName);
            }
            else
            {
                _sslServerCertificate = _certificateUtilsWrapper.GetMachineCertificateByFile(_sslCertificateFileName, _sslCertificatePassword);
            }
        }
        catch (Exception ex)
        {
            if (_certRefreshFrequency > TimeSpan.Zero)
            {
                _logger?.LogError(ex, "Unable to fetch certificate. It will be retried after {certificateRefreshRetryInterval}", _certificateRefreshRetryInterval);
                try
                {
                    _refreshTimer?.Change(_certificateRefreshRetryInterval, _certRefreshFrequency);
                }
                catch (ObjectDisposedException)
                {
                    // Timer is disposed
                }
            }
            else
            {
                // This is not a background timer based call
                _logger?.LogError(ex, "Unable to fetch certificate using the provided filename and password. Make sure you specify a correct CertFileName and CertPassword.");
            }
        }
    }
}
```

